public String colorful(int n) {
    String digits = Integer.toString(n);
    Set<Long> seen = new HashSet<>();
    for (int i = 0; i < digits.length(); i++) {
        for (int j = i; j < digits.length(); j++) {
            long product = 1;
            for (int k = i; k <= j; k++) {
                product *= digits.charAt(k) - '0';
            }
            if (!seen.add(product)) {
                return "NO";
            }
        }
    }
    return "YES";
}

