def colorful(self, n: int) -> str:
    digits = str(n)
    seen = set()
    for i in range(len(digits)):
        for j in range(i, len(digits)):
            product = 1
            for k in range(i, j + 1):
                product *= int(digits[k])
            if product in seen:
                return "NO"
            seen.add(product)
    return "YES"

